     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	    static final String SIGNATURE = "--\nPousada Maré Alta\n(79) 3200-0000 | @pousadamarealta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	
    20	    public ReservationService(
    21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.emailSender = emailSender;
    26	    }
    27	
    28	    public synchronized Reservation create(NewReservation request) {
    29	        if (!request.checkOut().isAfter(request.checkIn())) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    31	        }
    32	        if (request.guests() < 1) {
    33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    34	        }
    35	        Room room = rooms.find(request.roomNumber())
    36	                .orElseThrow(() -> new HotelException(
    37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    38	        if (request.guests() > room.capacity()) {
    39	            throw new HotelException(
    40	                    ErrorCode.CAPACITY_EXCEEDED,
    41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    42	        }
    43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    48	        return store.add(request, price);
    49	    }
    50	
    51	    public Reservation find(long reservationId) {
    52	        return store.find(reservationId)
    53	                .orElseThrow(() -> new HotelException(
    54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    55	    }
    56	
    57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    58	    public synchronized Reservation confirm(long reservationId) {
    59	        Reservation reservation = find(reservationId);
    60	        if (reservation.status() != ReservationStatus.PENDING) {
    61	            throw notAllowed(reservation, "confirm");
    62	        }
    63	        reservation.confirmPayment();
    64	        store.update(reservation);
    65	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    66	        emailSender.send(
    67	                reservation.guest().email(),
    68	                "Reserva confirmada - " + HOTEL_NAME,
    69	                confirmationEmailBody(reservation, receipt));
    70	        return reservation;
    71	    }
    72	
    73	    /**
    74	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    75	     * reservation was never paid, so nothing comes back).
    76	     */
    77	    public synchronized Reservation cancel(long reservationId) {
    78	        Reservation reservation = find(reservationId);
    79	        if (reservation.status() != ReservationStatus.PENDING
    80	                && reservation.status() != ReservationStatus.CONFIRMED) {
    81	            throw notAllowed(reservation, "cancel");
    82	        }
    83	        BigDecimal refund = switch (reservation.ratePlan()) {
    84	            case STANDARD -> reservation.amountPaid();
    85	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    86	        };
    87	        reservation.cancel(refund);
    88	        store.update(reservation);
    89	        return reservation;
    90	    }
    91	
    92	    public synchronized Reservation checkIn(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    95	            throw notAllowed(reservation, "check in");
    96	        }
    97	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    98	        store.update(reservation);
    99	        return reservation;
   100	    }
   101	
   102	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   103	    public synchronized ReservationReceipt checkOut(long reservationId) {
   104	        Reservation reservation = find(reservationId);
   105	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   106	            throw notAllowed(reservation, "check out");
   107	        }
   108	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   109	        store.update(reservation);
   110	        return new ReservationReceipt(reservation, roomOf(reservation));
   111	    }
   112	
   113	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   114	    public ReservationReceipt receiptCopy(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (!reservation.isPaid()) {
   117	            throw notAllowed(reservation, "issue a receipt for");
   118	        }
   119	        return new ReservationReceipt(reservation, roomOf(reservation));
   120	    }
   121	
   122	    private Room roomOf(Reservation reservation) {
   123	        return rooms.find(reservation.roomNumber()).orElseThrow();
   124	    }
   125	
   126	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   127	        return "Olá, " + reservation.guest().name() + "!\n\n"
   128	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   129	                + receipt.text() + "\n"
   130	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   131	                + "Até breve!\n\n"
   132	                + SIGNATURE;
   133	    }
   134	
   135	    private static HotelException notAllowed(Reservation reservation, String operation) {
   136	        return new HotelException(
   137	                ErrorCode.OPERATION_NOT_ALLOWED,
   138	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   139	    }
   140	}

