 10	import hotel.reservations.ErrorCode;
 11	import hotel.reservations.Guest;
 12	import hotel.reservations.HotelException;
 13	import hotel.reservations.NewReservation;
 14	import hotel.reservations.ReservationService;
 15	import hotel.rooms.Rooms;
 16	import io.javalin.Javalin;
 17	import io.javalin.http.Context;
 18	import io.javalin.json.JavalinJackson;
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeParseException;
 22	
 23	/** The HTTP API the inn's website and front desk call. */
 24	public final class HttpApi {
 25	
 26	    private final Javalin server;
 27	    private final Rooms rooms;
 28	    private final ReservationService reservations;
 29	    private final SentMessages sentMessages;
 30	    private final OccupancyReport occupancyReport;
 31	    private final RevenueReport revenueReport;
 32	
 33	    public HttpApi(
 34	            Rooms rooms,
 35	            ReservationService reservations,
 36	            SentMessages sentMessages,
 37	            OccupancyReport occupancyReport,
 38	            RevenueReport revenueReport) {
 39	        this.rooms = rooms;
 40	        this.reservations = reservations;
 41	        this.sentMessages = sentMessages;
 42	        this.occupancyReport = occupancyReport;
 43	        this.revenueReport = revenueReport;
 44	
 45	        ObjectMapper jsonMapper = JsonMapper.builder()
 46	                .addModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 48	                .build();
 49	        this.server = Javalin.create(config -> {
 50	            config.showJavalinBanner = false;
 51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 52	        });
 53	        registerRoutes();
 54	        registerErrorHandling();
 55	    }
 56	
 57	    public Javalin server() {
 58	        return server;
 59	    }
 60	
 61	    private void registerRoutes() {
 62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 63	
 64	        server.post("/reservations", ctx -> {
 65	            NewReservation request = readNewReservation(ctx);
 66	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
 67	        });
 68	        server.get("/reservations/{id}", ctx ->
 69	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
 70	        server.post("/reservations/{id}/confirmation", ctx ->
 71	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
 72	        server.post("/reservations/{id}/cancellation", ctx ->
 73	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
 74	        server.post("/reservations/{id}/check-in", ctx ->
 75	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
 76	        server.post("/reservations/{id}/check-out", ctx ->
 77	                ctx.json(reservations.checkOut(reservationId(ctx))));
 78	        server.get("/reservations/{id}/document", ctx ->
 79	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 80	
 81	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 82	
 83	        server.get("/reports/occupancy", ctx -> {
 84	            LocalDate night = readDate(ctx);
 85	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
 86	        });
 87	        server.get("/reports/revenue", ctx -> {
 88	            YearMonth month = readMonth(ctx);
 89	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
 90	        });
 91	    }
 92	
 93	    private void registerErrorHandling() {
 94	        server.exception(HotelException.class, (exception, ctx) -> {
 95	            ctx.status(httpStatus(exception.errorCode()));
 96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 97	        });
 98	    }
 99	
100	    private static int httpStatus(ErrorCode errorCode) {
101	        return switch (errorCode) {
102	            case INVALID_REQUEST -> 400;
103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
105	            case CAPACITY_EXCEEDED -> 422;
106	        };
107	    }
108	
109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || isBlank(body.guestCpf())
121	                || body.checkIn() == null
122	                || body.checkOut() == null
123	                || body.guests() == null
124	                || body.ratePlan() == null) {
125	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
126	        }
127	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
128	        return new NewReservation(
129	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
130	    }
131	
132	    private static long reservationId(Context ctx) {
133	        String id = ctx.pathParam("id");
134	        try {
135	            return Long.parseLong(id);
136	        } catch (NumberFormatException notANumber) {
137	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
138	        }
139	    }
140	
141	    private static LocalDate readDate(Context ctx) {
142	        String date = requiredQueryParam(ctx, "date");
143	        try {
144	            return LocalDate.parse(date);
145	        } catch (DateTimeParseException badDate) {
146	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
147	        }
148	    }
149	
150	    private static YearMonth readMonth(Context ctx) {
151	        String month = requiredQueryParam(ctx, "month");
152	        try {
153	            return YearMonth.parse(month);
154	        } catch (DateTimeParseException badMonth) {
155	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
156	        }
157	    }
158	
159	    private static String requiredQueryParam(Context ctx, String name) {
160	        String value = ctx.queryParam(name);
161	        if (value == null) {
162	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
163	        }
164	        return value;
165	    }
166	
167	    private static boolean isBlank(String text) {
168	        return text == null || text.isBlank();
169	    }
170	}
171	package hotel.reservations;
172	
173	import java.math.BigDecimal;
174	import java.sql.Connection;
175	import java.sql.Date;
176	import java.sql.PreparedStatement;
177	import java.sql.ResultSet;
178	import java.sql.SQLException;
179	import java.time.LocalDate;
180	import java.util.ArrayList;
181	import java.util.List;
182	import java.util.Optional;
183	import javax.sql.DataSource;
184	
185	/** Keeps the reservations in the database. */
186	public final class ReservationStore {
187	
188	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
189	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
190	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
191	    private static final String EXCLUSION_VIOLATION = "23P01";
192	
193	    private final DataSource dataSource;
194	
195	    public ReservationStore(DataSource dataSource) {
196	        this.dataSource = dataSource;
197	    }
198	
199	    /** Saves a new reservation; the database numbers it. */
200	    Reservation add(NewReservation request, Price price) {
201	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
202	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
203	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
204	        try (Connection connection = dataSource.getConnection();
205	                PreparedStatement statement = connection.prepareStatement(insert)) {
206	            statement.setInt(1, request.roomNumber());
207	            statement.setString(2, request.guest().name());
208	            statement.setString(3, request.guest().email());
209	            statement.setString(4, request.guest().cpf());
210	            statement.setDate(5, Date.valueOf(request.checkIn()));
211	            statement.setDate(6, Date.valueOf(request.checkOut()));
212	            statement.setInt(7, request.guests());
213	            statement.setString(8, request.ratePlan().name());
214	            statement.setInt(9, price.nights());
215	            statement.setBigDecimal(10, price.subtotal());
216	            statement.setBigDecimal(11, price.discount());
217	            statement.setBigDecimal(12, price.total());
218	            statement.setString(13, ReservationStatus.PENDING.name());
219	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
220	            try (ResultSet generated = statement.executeQuery()) {
221	                generated.next();
222	                return new Reservation(generated.getLong("id"), request, price);
223	            }
224	        } catch (SQLException failure) {
225	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
226	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
227	                        "room " + request.roomNumber() + " is taken on some of those nights");
228	            }
229	            throw new IllegalStateException("could not save the reservation", failure);
230	        }
231	    }
232	
233	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
234	    void update(Reservation reservation) {
235	        try (Connection connection = dataSource.getConnection();
236	                PreparedStatement statement = connection.prepareStatement(
237	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
238	            statement.setString(1, reservation.status().name());
239	            statement.setBigDecimal(2, reservation.amountPaid());
240	            statement.setBigDecimal(3, reservation.refund());
241	            statement.setLong(4, reservation.id());
242	            statement.executeUpdate();
243	        } catch (SQLException failure) {
244	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
245	        }
246	    }
247	
248	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
249	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
250	        try (Connection connection = dataSource.getConnection();
251	                PreparedStatement select = connection.prepareStatement(
252	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
253	                                + "AND check_in < ? AND ? < check_out")) {
254	            select.setInt(1, roomNumber);
255	            select.setDate(2, Date.valueOf(checkOut));
256	            select.setDate(3, Date.valueOf(checkIn));
257	            try (ResultSet rows = select.executeQuery()) {
258	                return rows.next();
259	            }
260	        } catch (SQLException failure) {
261	            throw new IllegalStateException("could not check room " + roomNumber, failure);
262	        }
263	    }
264	
265	    public Optional<Reservation> find(long id) {
266	        try (Connection connection = dataSource.getConnection();
267	                PreparedStatement select = connection.prepareStatement(
268	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
269	            select.setLong(1, id);
270	            try (ResultSet rows = select.executeQuery()) {
271	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
272	            }
273	        } catch (SQLException failure) {
274	            throw new IllegalStateException("could not read reservation " + id, failure);
275	        }
276	    }
277	
278	    public List<Reservation> all() {
279	        try (Connection connection = dataSource.getConnection();
280	                PreparedStatement select = connection.prepareStatement(
281	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
282	                ResultSet rows = select.executeQuery()) {
283	            List<Reservation> reservations = new ArrayList<>();
284	            while (rows.next()) {
285	                reservations.add(read(rows));
286	            }
287	            return reservations;
288	        } catch (SQLException failure) {
289	            throw new IllegalStateException("could not read the reservations", failure);
290	        }
291	    }
292	
293	    private static Reservation read(ResultSet row) throws SQLException {
294	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
295	        NewReservation request = new NewReservation(
296	                row.getInt("room_number"),
297	                guest,
298	                row.getDate("check_in").toLocalDate(),
299	                row.getDate("check_out").toLocalDate(),
300	                row.getInt("guests"),
301	                RatePlan.valueOf(row.getString("rate_plan")));
302	        Price price = new Price(
303	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
304	                row.getBigDecimal("total"));
305	        return new Reservation(
306	                row.getLong("id"),
307	                request,
308	                price,
309	                ReservationStatus.valueOf(row.getString("status")),
310	                row.getBigDecimal("amount_paid"),
311	                row.getBigDecimal("refund"));
312	    }
313	}
