323	import hotel.rooms.Rooms;
324	import hotel.web.HttpApi;
325	import io.javalin.Javalin;
326	import javax.sql.DataSource;
327	
328	/** Puts the inn's pieces together and runs the HTTP server. */
329	public final class Hotel {
330	
331	    private final Javalin server;
332	
333	    public Hotel(DataSource dataSource) {
334	        Rooms rooms = new Rooms(dataSource);
335	        ReservationStore store = new ReservationStore(dataSource);
336	        SentMessages sentMessages = new SentMessages(dataSource);
337	        ReservationService reservations =
338	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
339	        HttpApi api = new HttpApi(
340	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
341	        this.server = api.server();
342	    }
343	
344	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
345	    public int start(int port) {
346	        server.start(port);
347	        return server.port();
348	    }
349	
350	    public void stop() {
351	        server.stop();
352	    }
353	
354	    public static void main(String[] args) {
355	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
356	        Database database = new Database(System.getenv());
357	        new Hotel(database.dataSource()).start(port);
358	    }
359	}

