171	package hotel.reservations;
172	
173	import java.math.BigDecimal;
174	import java.sql.Connection;
175	import java.sql.Date;
176	import java.sql.PreparedStatement;
177	import java.sql.ResultSet;
178	import java.sql.SQLException;
179	import java.time.LocalDate;
180	import java.util.ArrayList;
181	import java.util.List;
182	import java.util.Optional;
183	import javax.sql.DataSource;
184	
185	/** Keeps the reservations in the database. */
186	public final class ReservationStore {
187	
188	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
189	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
190	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
191	    private static final String EXCLUSION_VIOLATION = "23P01";
192	
193	    private final DataSource dataSource;
194	
195	    public ReservationStore(DataSource dataSource) {
196	        this.dataSource = dataSource;
197	    }
198	
199	    /** Saves a new reservation; the database numbers it. */
200	    Reservation add(NewReservation request, Price price) {
201	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
202	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
203	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
204	        try (Connection connection = dataSource.getConnection();
205	                PreparedStatement statement = connection.prepareStatement(insert)) {
206	            statement.setInt(1, request.roomNumber());
207	            statement.setString(2, request.guest().name());
208	            statement.setString(3, request.guest().email());
209	            statement.setString(4, request.guest().cpf());
210	            statement.setDate(5, Date.valueOf(request.checkIn()));
211	            statement.setDate(6, Date.valueOf(request.checkOut()));
212	            statement.setInt(7, request.guests());
213	            statement.setString(8, request.ratePlan().name());
214	            statement.setInt(9, price.nights());
215	            statement.setBigDecimal(10, price.subtotal());
216	            statement.setBigDecimal(11, price.discount());
217	            statement.setBigDecimal(12, price.total());
218	            statement.setString(13, ReservationStatus.PENDING.name());
219	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
220	            try (ResultSet generated = statement.executeQuery()) {
221	                generated.next();
222	                return new Reservation(generated.getLong("id"), request, price);
223	            }
224	        } catch (SQLException failure) {
225	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
226	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
227	                        "room " + request.roomNumber() + " is taken on some of those nights");
228	            }
229	            throw new IllegalStateException("could not save the reservation", failure);
230	        }
231	    }
232	
233	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
234	    void update(Reservation reservation) {
235	        try (Connection connection = dataSource.getConnection();
236	                PreparedStatement statement = connection.prepareStatement(
237	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
238	            statement.setString(1, reservation.status().name());
239	            statement.setBigDecimal(2, reservation.amountPaid());
240	            statement.setBigDecimal(3, reservation.refund());
241	            statement.setLong(4, reservation.id());
242	            statement.executeUpdate();
243	        } catch (SQLException failure) {
244	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
245	        }
246	    }
247	
248	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
249	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
250	        try (Connection connection = dataSource.getConnection();
251	                PreparedStatement select = connection.prepareStatement(
252	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
253	                                + "AND check_in < ? AND ? < check_out")) {
254	            select.setInt(1, roomNumber);
255	            select.setDate(2, Date.valueOf(checkOut));
256	            select.setDate(3, Date.valueOf(checkIn));
257	            try (ResultSet rows = select.executeQuery()) {
258	                return rows.next();
259	            }
260	        } catch (SQLException failure) {
261	            throw new IllegalStateException("could not check room " + roomNumber, failure);
262	        }
263	    }
264	
265	    public Optional<Reservation> find(long id) {
266	        try (Connection connection = dataSource.getConnection();
267	                PreparedStatement select = connection.prepareStatement(
268	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
269	            select.setLong(1, id);
270	            try (ResultSet rows = select.executeQuery()) {
271	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
272	            }
273	        } catch (SQLException failure) {
274	            throw new IllegalStateException("could not read reservation " + id, failure);
275	        }
276	    }
277	
278	    public List<Reservation> all() {
279	        try (Connection connection = dataSource.getConnection();
280	                PreparedStatement select = connection.prepareStatement(
281	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
282	                ResultSet rows = select.executeQuery()) {
283	            List<Reservation> reservations = new ArrayList<>();
284	            while (rows.next()) {
285	                reservations.add(read(rows));
286	            }
287	            return reservations;
288	        } catch (SQLException failure) {
289	            throw new IllegalStateException("could not read the reservations", failure);
290	        }
291	    }
292	
293	    private static Reservation read(ResultSet row) throws SQLException {
294	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
295	        NewReservation request = new NewReservation(
296	                row.getInt("room_number"),
297	                guest,
298	                row.getDate("check_in").toLocalDate(),
299	                row.getDate("check_out").toLocalDate(),
300	                row.getInt("guests"),
301	                RatePlan.valueOf(row.getString("rate_plan")));
302	        Price price = new Price(
303	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
304	                row.getBigDecimal("total"));
305	        return new Reservation(
306	                row.getLong("id"),
307	                request,
308	                price,
309	                ReservationStatus.valueOf(row.getString("status")),
310	                row.getBigDecimal("amount_paid"),
311	                row.getBigDecimal("refund"));
312	    }
313	}
